INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 0, 'received', 'Hallo! Darf ich fragen, wie du heißt?', NULL, 'Hello! May I ask what your name is?', 'سلام! می‌تونم بپرسم اسمت چیه؟' FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 1, 'sent', NULL, 'Hallo! Mein Name ist Lukas.', 'Hello! My name is Lukas.', 'سلام! اسم من لوکاس هست.' FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 2, 'received', 'Woher kommst du?', NULL, 'Where are you from?', 'اهل کجایی؟' FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 3, 'sent', NULL, 'Ich komme ursprünglich aus Spanien, aber jetzt wohne ich in Berlin.', 'I am originally from Spain, but now I live in Berlin.', 'من اصالتاً اهل اسپانیا هستم، ولی الان در برلین زندگی می‌کنم.' FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 4, 'received', 'Interessant! Was machst du beruflich?', NULL, 'Interesting! What do you do for work?', 'جالبه! شغلت چیه؟' FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 5, 'sent', NULL, 'Ich arbeite als Softwareentwickler.', 'I work as a software developer.', 'من برنامه‌نویس هستم.' FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 6, 'received', 'Und was machst du in deiner Freizeit?', NULL, 'And what do you do in your free time?', 'و تو وقت آزادت چیکار می‌کنی؟' FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 7, 'sent', NULL, 'Ich spiele gerne Fußball und reise sehr gerne.', 'I like playing football and love travelling.', 'فوتبال بازی می‌کنم و سفر کردن رو دوست دارم.' FROM lessons WHERE day = 1;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 0, 'received', 'Hallo! Guten Morgen!', NULL, 'Hello! Good morning!', 'سلام! صبح بخیر!' FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 1, 'sent', NULL, 'Guten Morgen! Wie geht es Ihnen?', 'Good morning! How are you?', 'صبح بخیر! حالتون چطوره؟' FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 2, 'received', 'Danke, mir geht es gut. Und Ihnen?', NULL, 'Thanks, I''m fine. And you?', 'ممنون، حالم خوبه. و شما؟' FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 3, 'sent', NULL, 'Auch gut, danke.', 'Also good, thanks.', 'منم خوبم، ممنون.' FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 4, 'received', 'Schön, Sie zu treffen. Auf Wiedersehen!', NULL, 'Nice to meet you. Goodbye!', 'خوشحال شدم. خداحافظ!' FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 5, 'sent', NULL, 'Auf Wiedersehen! Tschüss!', 'Goodbye! Bye!', 'خداحافظ! بای!' FROM lessons WHERE day = 2;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 0, 'received', 'Hallo! Wie geht''s?', NULL, 'Hello! How are you?', 'سلام! چطوری؟' FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 1, 'sent', NULL, 'Hallo! Es geht mir gut, danke.', 'Hello! I''m fine, thanks.', 'سلام! خوبم، ممنون.' FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 2, 'received', 'Nur gut? Du siehst ein bisschen müde aus.', NULL, 'Just fine? You look a little tired.', 'فقط خوب؟ یه کم خسته به نظر می‌رسی.' FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 3, 'sent', NULL, 'Ja, ich bin ein bisschen müde. Ich habe nicht gut geschlafen.', 'Yes, I am a little tired. I didn''t sleep well.', 'آره، یه کم خستم. خوب نخوابیدم.' FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 4, 'received', 'Das kenne ich. Und wie geht es deiner Familie?', NULL, 'I know that feeling. And how is your family?', 'می‌فهمم. خانواده‌ات چطورن؟' FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 5, 'sent', NULL, 'Denen geht es gut, danke der Nachfrage.', 'They''re fine, thanks for asking.', 'اونا خوبن، ممنون که پرسیدی.' FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 6, 'received', 'Das ist schön. Erhol dich gut!', NULL, 'That''s great. Get some rest!', 'عالیه. استراحت کن!' FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 7, 'sent', NULL, 'Danke! Dir auch einen schönen Tag.', 'Thanks! Have a nice day too.', 'ممنون! روز خوبی داشته باشی.' FROM lessons WHERE day = 3;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 0, 'received', 'Wie alt bist du?', NULL, 'How old are you?', 'چند سالته؟' FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 1, 'sent', NULL, 'Ich bin achtundzwanzig Jahre alt.', 'I am twenty-eight years old.', 'من ۲۸ سالمه.' FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 2, 'received', 'Und wie ist deine Handynummer?', NULL, 'And what is your phone number?', 'شماره موبایلت چنده؟' FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 3, 'sent', NULL, 'Meine Nummer ist null-eins-sieben-drei, vier-fünf-sechs-sieben-acht-neun.', 'My number is 0173, 456789.', 'شماره‌ام اینه: ۰۱۷۳، ۴۵۶۷۸۹.' FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 4, 'received', 'In welchem Jahr bist du geboren?', NULL, 'In what year were you born?', 'چه سالی به دنیا اومدی؟' FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 5, 'sent', NULL, 'Ich bin neunzehnhundertneunundneunzig geboren.', 'I was born in nineteen ninety-nine.', 'سال ۱۹۹۹ به دنیا اومدم.' FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 6, 'received', 'Wie viele Geschwister hast du?', NULL, 'How many siblings do you have?', 'چند تا خواهر و برادر داری؟' FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 7, 'sent', NULL, 'Ich habe zwei Geschwister — einen Bruder und eine Schwester.', 'I have two siblings — one brother and one sister.', 'دو تا خواهر برادر دارم — یه برادر و یه خواهر.' FROM lessons WHERE day = 4;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 0, 'received', 'Welcher Tag ist heute?', NULL, 'What day is today?', 'امروز چه روزیه؟' FROM lessons WHERE day = 5;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 1, 'sent', NULL, 'Heute ist Montag.', 'Today is Monday.', 'امروز دوشنبه‌ست.' FROM lessons WHERE day = 5;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 2, 'received', 'Und welches Datum haben wir?', NULL, 'And what is the date today?', 'تاریخ امروز چنده؟' FROM lessons WHERE day = 5;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 3, 'sent', NULL, 'Heute ist der fünfzehnte März.', 'Today is the fifteenth of March.', 'امروز پانزدهم مارس هست.' FROM lessons WHERE day = 5;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 4, 'received', 'Wann hast du Geburtstag?', NULL, 'When is your birthday?', 'تولدت کیه؟' FROM lessons WHERE day = 5;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 5, 'sent', NULL, 'Ich habe am dritten Juli Geburtstag.', 'My birthday is on the third of July.', 'تولدم سوم ژوئیه‌ست.' FROM lessons WHERE day = 5;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 6, 'received', 'In welchem Monat treffen wir uns das nächste Mal?', NULL, 'In which month do we meet next time?', 'چه ماهی دوباره همدیگه رو می‌بینیم؟' FROM lessons WHERE day = 5;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 7, 'sent', NULL, 'Wir treffen uns im nächsten September.', 'We''ll meet next September.', 'سپتامبر بعدی همدیگه رو می‌بینیم.' FROM lessons WHERE day = 5;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 0, 'received', 'Erzähl mir von deiner Familie.', NULL, 'Tell me about your family.', 'از خانواده‌ات برام بگو.' FROM lessons WHERE day = 6;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 1, 'sent', NULL, 'Ich habe eine kleine Familie. Meine Eltern leben in München.', 'I have a small family. My parents live in Munich.', 'خانواده کوچکی دارم. پدر و مادرم در مونیخ زندگی می‌کنن.' FROM lessons WHERE day = 6;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 2, 'received', 'Hast du Geschwister?', NULL, 'Do you have siblings?', 'خواهر یا برادر داری؟' FROM lessons WHERE day = 6;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 3, 'sent', NULL, 'Ja, ich habe eine ältere Schwester. Sie ist verheiratet und hat zwei Kinder.', 'Yes, I have an older sister. She is married and has two children.', 'آره، یه خواهر بزرگتر دارم. اون ازدواج کرده و دو تا بچه داره.' FROM lessons WHERE day = 6;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 4, 'received', 'Und du? Bist du verheiratet?', NULL, 'And you? Are you married?', 'و تو؟ ازدواج کردی؟' FROM lessons WHERE day = 6;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 5, 'sent', NULL, 'Nein, ich bin noch ledig. Aber ich habe eine Freundin.', 'No, I am still single. But I have a girlfriend.', 'نه، هنوز مجردم. ولی دوست‌دختر دارم.' FROM lessons WHERE day = 6;
