INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 4, 'received', 'Es steht auf dem Tischaufsteller: Kaffee2024.', NULL, 'It''s on the table card: Kaffee2024.', 'روی تابلوی روی میز نوشته: Kaffee2024.' FROM lessons WHERE day = 45;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 5, 'sent', NULL, 'Danke! Kann ich hier auch meinen Laptop aufladen?', 'Thanks! Can I also charge my laptop here?', 'ممنون! می‌تونم لپ‌تاپم رو هم اینجا شارژ کنم؟' FROM lessons WHERE day = 45;
