INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 2, 'received', 'Bei mir zu Hause, ab sieben Uhr abends.', NULL, 'At my place, starting at seven in the evening.', 'خونه‌ام، از ساعت هفت شب.' FROM lessons WHERE day = 46;
