INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 14, 'sent', NULL, 'Sie gefällt mir sehr gut. Ich würde sie gerne nehmen.', 'I really like it. I''d like to take it.', 'خیلی دوستش دارم. می‌خوام بگیرمش.' FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 15, 'received', 'Sehr gut! Ich schicke Ihnen den Mietvertrag zu.', NULL, 'Great! I''ll send you the rental contract.', 'عالی! قرارداد اجاره رو برای شما می‌فرستم.' FROM lessons WHERE day = 56;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 0, 'sent', NULL, 'Hallo, ich habe ein Problem mit meinem Internet. Es funktioniert nicht.', 'Hello, I have a problem with my internet. It''s not working.', 'سلام، با اینترنتم مشکل دارم. کار نمیکنه.' FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 1, 'received', 'Guten Tag. Was genau ist das Problem?', NULL, 'Good day. What exactly is the problem?', 'روز بخیر. مشکل دقیقاً چیه؟' FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 2, 'sent', NULL, 'Die Verbindung bricht immer wieder ab. Der Router zeigt ein rotes Licht.', 'The connection keeps dropping. The router shows a red light.', 'اتصال قطع و وصل میشه. روتر چراغ قرمز نشون میده.' FROM lessons WHERE day = 57;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 3, 'received', 'Haben Sie versucht, den Router neu zu starten?', NULL, 'Have you tried restarting the router?', 'روتر رو ریستارت کردید؟' FROM lessons WHERE day = 57;
