INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 8, 'sent', NULL, 'Wann wird das Problem behoben?', 'When will it be fixed?', 'کِی درست میشه؟' FROM lessons WHERE day = 57;
