INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 4, 'sent', NULL, 'Vor ungefähr zwanzig Minuten, auf der Linie U3.', 'About twenty minutes ago, on the U3 line.', 'حدود بیست دقیقه پیش، تو خط U3.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 5, 'received', 'Befanden sich Dokumente in dem Geldbeutel?', NULL, 'Were there any documents in the wallet?', 'مدرکی توی کیف پول بود؟' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 6, 'sent', NULL, 'Ja, mein Reisepass und meine Kreditkarte waren drin.', 'Yes, my passport and credit card were in it.', 'بله، پاسپورتم و کارت اعتباریم توش بود.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 7, 'received', 'Sie müssen sofort Ihre Kreditkarte sperren lassen.', NULL, 'You must have your credit card blocked immediately.', 'باید فوری کارت اعتباریتون رو مسدود کنید.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 8, 'sent', NULL, 'Wie kann ich das tun? Ich bin Tourist und kenne die Nummer nicht.', 'How can I do that? I''m a tourist and don''t know the number.', 'چطور میتونم این کارو بکنم؟ من توریستم و شماره رو نمیدونم.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 9, 'received', 'Wir können Ihnen dabei helfen. Welche Bank war das?', NULL, 'We can help you with that. Which bank was it?', 'ما می‌تونیم کمکتون کنیم. کدوم بانک بود؟' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 10, 'sent', NULL, 'Es war eine Visa-Karte von meiner deutschen Bank.', 'It was a Visa card from my German bank.', 'یه کارت ویزا از بانک آلمانیم بود.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 11, 'received', 'Gut. Wir leiten Sie weiter. Und für den Pass müssen Sie zur Botschaft.', NULL, 'Good. We''ll transfer you. And for the passport you''ll need to go to the embassy.', 'خوب. شما رو وصل می‌کنیم. و برای پاسپورت باید برید سفارتخونه.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 12, 'sent', NULL, 'Kann ich hier eine Verlustanzeige machen?', 'Can I file a loss report here?', 'میتونم اینجا گزارش گم‌شدن بدم؟' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 13, 'received', 'Ja, natürlich. Ich nehme Ihre persönlichen Daten auf.', NULL, 'Yes, of course. I''ll take your personal details.', 'بله، البته. مشخصات شخصیتون رو می‌گیرم.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 14, 'sent', NULL, 'Mein Name ist Kamran Hosseini, geboren am dritten März neunzehnneunzig.', 'My name is Kamran Hosseini, born on the third of March, 1999.', 'اسمم کامران حسینی هست، متولد سوم مارس هزار و نهصد و نود و نه.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 15, 'received', 'Danke. Haben Sie eine Adresse in Deutschland, unter der wir Sie erreichen können?', NULL, 'Thank you. Do you have an address in Germany where we can reach you?', 'ممنون. آدرسی در آلمان دارید که بتونیم باهاتون تماس بگیریم؟' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 16, 'sent', NULL, 'Ja, ich wohne im Hotel Zentrum, Zimmer dreizehn.', 'Yes, I''m staying at Hotel Zentrum, room thirteen.', 'بله، در هتل تسنتروم اتاق سیزده اقامت دارم.' FROM lessons WHERE day = 60;
INSERT INTO sentences (lesson_id, sentence_order, role, audio_text, target_text, translation, translation_fa) SELECT id, 17, 'received', 'Alles klar. Hier ist Ihre Anzeigenummer: 2024-8831. Bitte bewahren Sie diese gut auf.', NULL, 'All right. Here is your report number: 2024-8831. Please keep it safe.', 'باشه. شماره گزارشتون اینه: ۲۰۲۴-۸۸۳۱. لطفاً خوب نگهش دارید.' FROM lessons WHERE day = 60;
